<include file="Public:header"/><link rel="stylesheet" href="{pigcms{$static_path}css/bootstrap.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/font-awesome.min.css?t=01"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui.css"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-fonts.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace.min.css" id="main-ace-style"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-skins.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-rtl.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/global.css"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui-timepicker-addon.css"><link rel="stylesheet" href="{pigcms{$static_public}layui/css/layui.css"  media="all"><script type="text/javascript" src="{pigcms{$static_path}js/bootstrap.min.js"></script><script src="{pigcms{$static_public}layui2/layui.all.js" charset="utf-8"></script><style>    .table-list .summary {        margin: 10px 25px 5px 0 !important;        text-align: right !important;    }    .table-list .pager {        margin: 0 25px 5px 0 !important;        text-align: right !important;    }    .pager .next>a {        height: 30px;        line-height: 30px;    }    .pager .prev>a {        height: 30px;        line-height: 30px;    }   .input{ width: 300px;height: 30px;    line-height: 30px;}    .right_div{        display: inline-block;    margin-left: 50px;    }    .ant-btn {        line-height: 1.499;        position: relative;        display: inline-block;        font-weight: 400;        white-space: nowrap;        text-align: center;        background-image: none;        border: 1px solid transparent;        -webkit-box-shadow: 0 2px 0 rgb(0 0 0 / 2%);        box-shadow: 0 2px 0 rgb(0 0 0 / 2%);        cursor: pointer;        -webkit-transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);        transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);        -webkit-user-select: none;        -moz-user-select: none;        -ms-user-select: none;        user-select: none;        -ms-touch-action: manipulation;        touch-action: manipulation;        height: 32px;        padding: 0 15px;        font-size: 14px;        border-radius: 2px;        color: #fff;        background-color: #1890ff;        text-shadow: 0 -1px 0 rgb(0 0 0 / 12%);}</style>	<div class="mainbox" style="background-color: #fff;min-height: 590px;">       <div class="tabbable" style="height: 60px;">            <ul id="myTab" class="nav nav-tabs" style="height: 35px;margin-top:0px;">                <li <if condition="$getparam['activetab'] neq 'datalist'">class="active"</if> >                    <a href="javascript:;" data-toggle="tab" onclick="toggleNavTab('basicinfo_div')">{pigcms{$block_type_str}设置</a>                </li>                <php>                 $getTmpparam=$_GET;                 $getTmpparam['activetab']='datalist';                </php>                <li <if condition="$getparam['activetab'] eq 'datalist'">class="active"</if> >                    <a href="{pigcms{:U('House/house_nav_guess_love',$getTmpparam)}" class="on">{pigcms{$block_type_str}列表</a></a>                </li>            </ul>        </div>      <div id="basicinfo_div" class="tab_div <if condition="$getparam['activetab'] eq 'datalist'">hide</if>" >        <input type="hidden" class="input set_input" name="block_type_id" id="block_type_id" value="{pigcms{$block_type_id}"/>        <input type="hidden" class="input set_input" name="village_id" value="{pigcms{$village_id}"/>         <if condition="$block_type_id eq 'business_classify_info'">        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>是否展示</label></label>            <div class="radio" style="padding-top: 5px;">                <label style="padding-left:0px;padding-right:20px;"><input name="is_show" value="1" type="radio" class="ace set_input"  <if condition="empty($nav_set) OR ($nav_set AND $nav_set.is_show eq 1)">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;展示</span></label>                <label style="padding-left:0px;"><input name="is_show" value="0" type="radio" class="ace set_input" <if condition="$nav_set AND $nav_set.is_show eq 0">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;不展示</span></label>            </div>        </div>       <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label class="red">*主标题：</label></label>            <div class="radio" style="padding-top: 5px;">                <input type="text" class="input set_input" id="set_input_title" name="title" value="{pigcms{$nav_set.title}" placeholder="6个汉字以内" maxlength="6" required /> &nbsp;&nbsp;&nbsp;(必填项)            </div>        </div>       <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>副标题：</label></label>            <div class="radio" style="padding-top: 5px;">                <input type="text" class="input set_input" name="sub_title" value="{pigcms{$nav_set.sub_title}" placeholder="10个汉字以内" maxlength="10"/>            </div>        </div>        </if>        <if condition="$block_type_id eq 'business_store_info'">            <div class="form-group">                <label class="col-sm-1" style="width: 15%;"><label>是否显示装修内容</label></label>                <div class="radio" style="padding-top: 5px;">                    <label style="padding-left:0px;padding-right:20px;"><input name="is_show" value="1" type="radio" class="ace set_input"  <if condition="empty($nav_set) OR ($nav_set AND $nav_set.is_show eq 1)">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;开启</span></label>                    <label style="padding-left:0px;"><input name="is_show" value="0" type="radio" class="ace set_input" <if condition="$nav_set AND $nav_set.is_show eq 0">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;关闭</span></label>                </div>            </div>           <div style="margin-left: 10px;color: #9a9999">            <span> 说明：</span>                <p>1.开关按钮默认开启</p>                <p>2.按钮开关不控制系统的店铺推荐，将控制自定义装修内容，关闭则装修的不展示</p>            </div>         </if>         <div style="text-align:center;margin-top: 50px;">               <button type="button" onclick="saveNavSetData()" class="ant-btn ant-btn-primary" >保存设置</button>           </div>        </div>        <div id="datalist_div" class="tab_div <if condition="$getparam['activetab'] neq 'datalist'">hide</if>">        <div style="margin-left: 10px;color: #9a9999">        </div>		<div id="nav" class="mainnav_title">            <php>                 $getparam=$_GET;                 $getparam['activetab']='datalist';            </php>			<ul>				<a href="{pigcms{:U('House/house_nav_guess_love',$getparam)}" class="on">首页自定义导航列表</a>                <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('House/nav_add_guess_love',array('block_type_id' => $block_type_id,'is_community_platform'=>1))}','添加导航',850,580,true,false,false,addbtn,'add',true,'refreshPage');">添加导航</a>			</ul>		</div>				<form name="myform" id="myform" action="" method="post">			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>                    <tr>                        <th>编号</th>                     <if condition="$block_type_id eq 'business_store_info'">                            <th>标题</th>                            <th>店铺分类名称</th>                            <th>店铺展示数量</th>                                                        <else />							<th>分类名称</th>                            <th>副标题</th>                     </if>							<th>排序</th>							<th>状态</th>                            <th class="textcenter">操作</th>						</tr>					</thead>					<tbody>						<if condition="is_array($result['list'])">							<volist name="result['list']" id="vo">								<tr>                                <td>{pigcms{$vo.id}</td>                                <if condition="$block_type_id eq 'business_store_info'">								    <td>{pigcms{$vo.name}</td>                                    <td>{pigcms{$vo.classify_name}</td>									<td>{pigcms{$vo.business_num}</td>                                    <else />                                    <td>{pigcms{$vo.classify_name}</td>									<td>{pigcms{$vo.name}</td>                                    </if>									<td>{pigcms{$vo.sort}</td>									<td>									<if condition="$vo['status'] eq 1">										<font color="green">正常</font>									<elseif condition="$vo['status'] eq 0"/>										<font color="red">关闭</font>									</if></td>									<td class="textcenter">                                       <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('House/nav_add_guess_love',array('id'=>$vo['id'],'block_type_id' => $block_type_id,'is_community_platform'=>1,'from_page'=>$_GET['from_page']))}','编辑导航信息',850,580,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('House/nav_del_new')}">删除</a>                                    </td>                                   								</tr>							</volist>						<else/>							<tr>                                <td class="textcenter red"  <if condition="($assign_type['type_2'] && $row_type neq single) || ($assign_type['type_11'] && $row_type eq single)"> colspan="5" <else/>colspan="4"</if>>列表为空！</td>                            </tr>						</if>					</tbody>				</table>                {pigcms{$result.pagebar}			</div>		</form>        </div>	</div><script type="text/javascript" charset="utf-8">   function saveNavSetData(){       var inputArr=$('#basicinfo_div .set_input').serializeArray();       console.log('inputArr',inputArr);       var set_input_title=$('#set_input_title').val()||'';       set_input_title=$.trim(set_input_title);       if($('#set_input_title').size()>0 && !set_input_title){            layer.alert('请填写标题！');            return false;       }       $.post("{pigcms{:U('save_village_nav_set')}",inputArr,function(result){            if(result.status != 1){                layer.alert('保存成功,请重试~ ');            }else{                layer.alert('保存成功！');            }        },'json');   }    function toggleNavTab(idd){        $('.tab_div').addClass('hide');        $('#'+idd).removeClass('hide');    }    $(function(){        $("#choose_color_box_labeltxt").click(function(){            change_labelcolor();        });    });    function change_labelcolor(){        window.showTopColorPanel("leftmenu_Viewpage_index",$("#choose_color_box_labeltxt").offset().top,$("#choose_color_box_labeltxt").height(),$("#choose_color_box_labeltxt").offset().left,"config_labelcolor",function(){            var bgcolor = $('#config_labelcolor').val();            $('.page-style').css('background-color', bgcolor);        });    }</script><include file="Public:footer"/>